const API_URL = (window.__PUB_API_URL__ || 'http://127.0.0.1:3000').replace(/\/$/, '');
const state = { pubs: [], filtered: [], aiResults: null, aiContext: null, aiOffset: 0, aiVisibleCount: 6, aiLoadingMore: false, aiRequestId: 0, recommendationsExpanded: false, reviews: JSON.parse(localStorage.getItem('pub-discovery-reviews') || '{}'), ratings: JSON.parse(localStorage.getItem('pub-discovery-ratings') || '{}'), photos: JSON.parse(localStorage.getItem('pub-discovery-photos') || '{}'), visitCounts: JSON.parse(localStorage.getItem('pub-discovery-visit-counts') || '{}'), visited: new Set(JSON.parse(localStorage.getItem('pub-discovery-visited') || '[]')), saved: new Set(JSON.parse(localStorage.getItem('pub-discovery-saved') || '[]')), query: '', view: 'list', map: null, markers: null };
const $ = (selector) => document.querySelector(selector);
const GOOD_MATCH_THRESHOLD = 0.62;
const MINIMUM_MATCH_THRESHOLD = 0.5;

function persist() { localStorage.setItem('pub-discovery-visited', JSON.stringify([...state.visited])); localStorage.setItem('pub-discovery-saved', JSON.stringify([...state.saved])); localStorage.setItem('pub-discovery-reviews', JSON.stringify(state.reviews)); localStorage.setItem('pub-discovery-ratings', JSON.stringify(state.ratings)); localStorage.setItem('pub-discovery-photos', JSON.stringify(state.photos)); localStorage.setItem('pub-discovery-visit-counts', JSON.stringify(state.visitCounts)); updateCounts(); }
function updateCounts() { $('#nav-visited-count').textContent = state.visited.size; $('#nav-saved-count').textContent = state.saved.size; $('#visited-total').textContent = state.visited.size; $('#saved-total').textContent = state.saved.size; $('#discovered-total').textContent = state.pubs.length; const percent = state.pubs.length ? Math.round(state.visited.size / state.pubs.length * 100) : 0; $('#passport-percent').textContent = `${percent}%`; $('#progress-label').textContent = `${percent}% complete`; $('#progress-fill').style.width = `${percent}%`; }
function toast() {}
function safeUrl(value) { try { const url = new URL(value); return ['http:', 'https:'].includes(url.protocol) ? url.href : null; } catch { return null; } }
function normalizedTags(pub) { return Object.entries(pub.tags || {}).filter(([, value]) => value).map(([key, value]) => `${key} ${value}`.toLowerCase()).join(' '); }
function areaFor(pub) { const text = `${pub.address || ''} ${normalizedTags(pub)}`; if (/camden/i.test(text)) return 'Camden'; if (/westminster|soho|mayfair|pimlico/i.test(text)) return 'Westminster'; return 'London'; }
function areaFromQuery(query) { return ['Camden', 'Westminster', 'Waterloo', 'London Bridge', 'Shoreditch', 'Brixton'].find((area) => query.toLowerCase().includes(area.toLowerCase())) || null; }
function applyFilter() { const query = state.query.trim().toLowerCase(); const literalMatches = state.pubs.filter((pub) => !query || `${pub.name} ${pub.address || ''} ${normalizedTags(pub)}`.toLowerCase().includes(query)); const area = areaFromQuery(query); state.filtered = literalMatches.length || !area ? literalMatches : state.pubs.filter((pub) => areaFor(pub).toLowerCase() === area.toLowerCase()); if (query && !literalMatches.length && area) $('#status').textContent = `No exact matches for that request · showing ${area} pubs while verified details are checked`; renderResults(); }
function addPhoto(pub) { const input = document.createElement('input'); input.type = 'file'; input.accept = 'image/*'; input.multiple = true; input.hidden = true; input.addEventListener('change', () => { [...input.files].slice(0, 4).forEach((file) => { const reader = new FileReader(); reader.onload = () => { state.photos[pub.id] = [...(state.photos[pub.id] || []), String(reader.result)].slice(-8); persist(); renderAll(); toast('Photo added to your passport'); }; reader.readAsDataURL(file); }); input.remove(); }); document.body.append(input); input.click(); }
function mergeRecommendationPubs(items) { const known = new Map(state.pubs.map((pub) => [pub.id, pub])); items.forEach((item) => { if (!known.has(item.venueId)) known.set(item.venueId, { id: item.venueId, name: item.name, latitude: item.latitude, longitude: item.longitude, address: item.address, website: item.website, phone: item.phone, tags: {}, verifiedFeatures: item.verifiedFeatures || [] }); }); state.pubs = [...known.values()]; }

function card(pub, options = {}) {
  const recommended = options.recommended;
  const wrapper = document.createElement('article'); wrapper.className = `pub-card${recommended ? ' recommended' : ''}`; wrapper.dataset.pubId = pub.id;
  const matchScore = options.score ?? pub.recommendationScore;
  if (recommended) { const badge = document.createElement('span'); badge.className = `match-badge${matchScore >= GOOD_MATCH_THRESHOLD ? ' good' : ''}`; badge.textContent = matchScore >= GOOD_MATCH_THRESHOLD ? 'GOOD MATCH' : 'WORTH A LOOK'; wrapper.append(badge); }
  const top = document.createElement('div'); top.className = 'pub-top';
  const heading = document.createElement('div'); const title = document.createElement('h3'); title.className = 'pub-name'; title.textContent = pub.name; heading.append(title);
  const address = document.createElement('p'); address.className = 'pub-address'; address.textContent = `${areaFor(pub)} · ${pub.address || 'Address available on map'}`; heading.append(address); top.append(heading);
  if (matchScore != null) { const score = document.createElement('span'); score.className = 'score'; score.textContent = `${Math.round(matchScore * 100)}% match`; top.append(score); }
  wrapper.append(top);
  const facts = document.createElement('div'); facts.className = 'pub-facts'; const explanation = (options.reasons?.[0] || '').toLowerCase(); const personalReason = options.personalReason || pub.recommendationPersonalReason || ''; if (personalReason) { const match = personalReason.match(/^(Similar vibe to|Less similar to) (.+?)(?:, which you rated.*)?$/); const fact = document.createElement('span'); fact.className = 'fact personal-fact'; fact.textContent = match ? `${match[1] === 'Similar vibe to' ? 'Similar to' : 'Less like'} ${match[2]}` : personalReason; facts.append(fact); } const tags = [...(pub.verifiedFeatures || []), ...Object.values(pub.tags || {})].map((tag) => String(tag).replaceAll('_', ' ').replace(/\s+/g, ' ').trim()).filter((tag) => /food|music|dj|outdoor|sports|dog|historic|event|accessible|roast|vegan|quiz/i.test(tag) && !explanation.includes(tag.toLowerCase())); const uniqueTags = [...new Map(tags.map((tag) => [tag.toLowerCase(), tag])).values()].slice(0, 4); uniqueTags.forEach((tag) => { const fact = document.createElement('span'); fact.className = 'fact'; fact.textContent = tag; facts.append(fact); }); if (!facts.children.length && !explanation) { const fact = document.createElement('span'); fact.className = 'fact'; fact.textContent = 'London pub'; facts.append(fact); } wrapper.append(facts);
  if (options.passport || options.saved) { const review = document.createElement('div'); review.className = 'passport-memory'; if (state.reviews[pub.id]) { review.textContent = `“${state.reviews[pub.id]}”`; } else { review.textContent = 'No review yet'; } wrapper.append(review); const photos = state.photos[pub.id] || []; if (photos.length) { const gallery = document.createElement('div'); gallery.className = 'photo-grid'; photos.forEach((photo) => { const image = document.createElement('img'); image.src = photo; image.alt = `Memory from ${pub.name}`; gallery.append(image); }); wrapper.append(gallery); } }
  const actions = document.createElement('div'); actions.className = 'card-actions';
  const visited = state.visited.has(pub.id); if (visited) { const status = document.createElement('span'); status.className = 'visit-status'; status.textContent = 'Visited'; actions.append(status); const visit = document.createElement('button'); visit.className = 'visit-button visited'; visit.textContent = 'Unvisit'; visit.onclick = () => { state.visited.delete(pub.id); delete state.visitCounts[pub.id]; persist(); renderAll(); toast('Removed from your passport'); }; actions.append(visit); const photo = document.createElement('button'); photo.className = 'memory-action'; photo.textContent = 'Add photo'; photo.onclick = () => addPhoto(pub); actions.append(photo); const review = document.createElement('button'); review.className = 'memory-action'; review.textContent = state.reviews[pub.id] ? 'Edit review' : 'Add review'; review.onclick = () => openReviewForm(pub); actions.append(review); } else { const visit = document.createElement('button'); visit.className = 'visit-button'; visit.textContent = 'Mark visited'; visit.onclick = () => { if (!state.pubs.some((candidate) => candidate.id === pub.id)) state.pubs.push(pub); state.visited.add(pub.id); state.visitCounts[pub.id] = 1; persist(); renderAll(); toast('Added to your passport'); }; actions.append(visit); }
  const save = document.createElement('button'); save.className = `save-button${state.saved.has(pub.id) ? ' saved' : ''}`; save.textContent = state.saved.has(pub.id) ? '♥ Saved' : '♡ Save'; save.onclick = () => { if (!state.pubs.some((candidate) => candidate.id === pub.id)) state.pubs.push(pub); state.saved.has(pub.id) ? state.saved.delete(pub.id) : state.saved.add(pub.id); persist(); renderAll(); toast(state.saved.has(pub.id) ? 'Saved for later' : 'Removed from saved'); }; actions.append(save);
  const details = document.createElement('button'); details.textContent = 'Details'; details.onclick = () => showDetails(pub, options); actions.append(details); if ((options.passport || options.saved) && !visited) { const review = document.createElement('button'); review.textContent = state.reviews[pub.id] ? 'Edit review' : 'Add review'; review.onclick = () => openReviewForm(pub); actions.append(review); } wrapper.append(actions); return wrapper;
}

function aiPub(item) { const pub = state.pubs.find((candidate) => candidate.id === item.venueId); return pub ? { ...pub, recommendationScore: item.score, verifiedFeatures: item.verifiedFeatures || pub.verifiedFeatures } : { id: item.venueId, name: item.name, latitude: item.latitude, longitude: item.longitude, address: item.address, website: item.website, phone: item.phone, tags: {}, recommendationScore: item.score, verifiedFeatures: item.verifiedFeatures || [] }; }
function visiblePubs() { return state.aiResults === null ? state.filtered : state.aiResults.map(aiPub); }
function renderResults() { const container = $('#results'); container.replaceChildren(); const aiMode = state.aiResults !== null; $('#results-title').textContent = aiMode ? `AI recommendations for “${state.query}”` : state.query ? `Browse results for “${state.query}”` : 'Browse all pubs'; if (aiMode) { if (!state.aiResults.length) { const empty = document.createElement('div'); empty.className = 'empty-state'; empty.textContent = state.aiContext?.noResultReasons?.[0] || 'No verified matches for that request yet. Try a broader search.'; container.append(empty); return; } const visibleResults = state.recommendationsExpanded ? state.aiResults : state.aiResults.slice(0, 6); visibleResults.forEach((item) => container.append(card(aiPub(item), { recommended: true, reasons: item.reasons }))); if (state.aiResults.length > 6 || state.aiContext?.hasMore) { const more = document.createElement('button'); more.className = 'view-more-button'; more.textContent = state.recommendationsExpanded ? 'View less' : 'View more recommendations'; more.onclick = () => { if (state.recommendationsExpanded) { state.recommendationsExpanded = false; renderResults(); } else if (state.aiContext?.hasMore) void getRecommendations(state.aiResults.length, true); else { state.recommendationsExpanded = true; renderResults(); } }; container.append(more); } } else { if (!state.filtered.length) { const empty = document.createElement('div'); empty.className = 'empty-state'; empty.textContent = 'No pubs are available to browse yet.'; container.append(empty); return; } state.filtered.slice(0, 60).forEach((pub) => container.append(card(pub))); } if (state.view === 'map') renderMap(); }
function renderSuggestions(data) { const container = $('#suggestion-chips'); container.replaceChildren(); const suggestions = [['Live music', 'pub with live music'], ['Live sport', 'pub showing live sport'], ['Food', 'pub with food'], ['Outdoor seating', 'pub with outdoor seating'], ['Dog friendly', 'dog-friendly pub'], ['Sunday roast', 'pub serving a Sunday roast'], ['Quiz night', 'pub with a quiz night']]; const detected = [...(data?.recommendations || [])].flatMap((item) => item.verifiedFeatures || []).map((item) => item.toLowerCase()); suggestions.filter(([label]) => detected.some((feature) => feature.includes(label.toLowerCase().split(' ')[0]))).slice(0, 4).forEach(([label, query]) => { const button = document.createElement('button'); button.textContent = `Try ${label}`; button.onclick = () => { $('#query').value = query; state.query = query; void getRecommendations(); }; container.append(button); }); container.hidden = !container.children.length; }
document.addEventListener('click', (event) => { const target = event.target.closest('.visit-button'); if (!target || !target.textContent.includes('Mark visited')) return; const pubId = target.closest('.pub-card')?.dataset.pubId; const pub = state.pubs.find((candidate) => candidate.id === pubId); if (pub) window.setTimeout(() => openReviewForm(pub), 0); });
function openReviewForm(pub) { $('#review-title').textContent = pub.name; $('#review-text').value = state.reviews[pub.id] || ''; const dialog = $('#review-dialog'); const form = $('#review-form'); form.onsubmit = (event) => { event.preventDefault(); const value = $('#review-text').value.trim(); if (value) state.reviews[pub.id] = value; else delete state.reviews[pub.id]; persist(); renderPassport(); dialog.close(); toast(value ? 'Review added to your passport' : 'Review removed'); }; dialog.showModal(); }
function renderPassport() { const container = $('#passport-list'); container.replaceChildren(); const visited = state.pubs.filter((pub) => state.visited.has(pub.id)); if (!visited.length) { const empty = document.createElement('div'); empty.className = 'empty-state'; empty.textContent = 'Your passport is ready. Explore a pub and mark it visited to collect your first stamp.'; container.append(empty); } else visited.forEach((pub) => container.append(card(pub, { passport: true }))); }
function renderSaved() { const container = $('#saved-list'); container.replaceChildren(); const saved = state.pubs.filter((pub) => state.saved.has(pub.id)); if (!saved.length) { const empty = document.createElement('div'); empty.className = 'empty-state'; empty.textContent = 'No saved pubs yet. Tap Save on a pub to keep it here.'; container.append(empty); } else saved.forEach((pub) => container.append(card(pub, { saved: true }))); }
function renderAll() { updateCounts(); renderResults(); renderPassport(); renderSaved(); }

function showDetails(pub, options = {}) { const content = $('#detail-content'); content.replaceChildren(); const inner = document.createElement('div'); inner.className = 'detail-inner'; const eyebrow = document.createElement('p'); eyebrow.className = 'eyebrow'; eyebrow.textContent = options.recommended ? 'PERSONAL PICK' : areaFor(pub).toUpperCase(); inner.append(eyebrow); const title = document.createElement('h2'); title.textContent = pub.name; inner.append(title); const address = document.createElement('p'); address.className = 'pub-address'; address.textContent = pub.address || 'Address available on map'; inner.append(address); const body = document.createElement('div'); body.className = 'detail-body'; [['Area', areaFor(pub)], ['Opening hours', pub.openingHours || 'Not verified'], ['Website', pub.website || 'Not listed'], ['Phone', pub.phone || 'Not listed']].forEach(([label, value]) => { const row = document.createElement('div'); row.className = 'detail-row'; const left = document.createElement('span'); left.textContent = label; const right = document.createElement('strong'); if (label === 'Website' && safeUrl(value)) { const link = document.createElement('a'); link.href = safeUrl(value); link.target = '_blank'; link.rel = 'noopener'; link.textContent = 'Open website ↗'; right.append(link); } else right.textContent = value; row.append(left, right); body.append(row); }); inner.append(body); if (!pub.openingHours && pub.website) { const refresh = document.createElement('button'); refresh.className = 'refresh-hours'; refresh.textContent = 'Check official site for hours'; refresh.onclick = async () => { refresh.disabled = true; refresh.textContent = 'Checking official site…'; try { const response = await fetch(`${API_URL}/pubs/${encodeURIComponent(pub.id)}/refresh-hours`, { method: 'POST' }); if (!response.ok) throw new Error(); const data = await response.json(); if (data.openingHours) { pub.openingHours = data.openingHours; const stored = state.pubs.find((candidate) => candidate.id === pub.id); if (stored) stored.openingHours = data.openingHours; showDetails(pub, options); } else { refresh.textContent = 'No structured hours found on official site'; } } catch { refresh.textContent = 'Could not check the official site'; } }; inner.append(refresh); } content.append(inner); $('#detail-dialog').showModal(); }
async function getRecommendations(offset = 0, append = false) { const query = state.query.trim(); if (!query) { toast('Tell us what kind of pub you want first'); return; } if (!append) state.recommendationsExpanded = false; $('#status').textContent = append ? 'Finding more matches…' : 'AI is finding the best verified matches…'; try { const response = await fetch(`${API_URL}/recommendations`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ query, limit: 6, offset }) }); if (!response.ok) throw new Error(); const data = await response.json(); const qualifying = (data.recommendations || []).filter((item) => Number(item.score) >= MINIMUM_MATCH_THRESHOLD); state.aiResults = append ? [...state.aiResults, ...qualifying] : qualifying; state.recommendationsExpanded = append; state.aiContext = append ? { ...data, hasMore: false } : data; state.aiOffset = offset; renderSuggestions(data); $('#status').textContent = state.aiResults.length ? `${state.aiResults.length} thoughtful matches found` : 'No verified matches above 50% yet'; renderResults(); } catch { $('#status').textContent = 'Search is unavailable right now'; toast(`Could not reach the AI recommendation service at ${API_URL}`); } }
async function loadPubs() { try { const response = await fetch(`${API_URL}/pubs?limit=2000`); if (!response.ok) throw new Error(); const data = await response.json(); state.pubs = data.pubs || []; state.filtered = state.pubs; $('#status').textContent = `${state.pubs.length} pubs ready to explore`; renderAll(); } catch { try { const response = await fetch('sample-pubs.json'); state.pubs = await response.json(); state.filtered = state.pubs; $('#status').textContent = `${state.pubs.length} demo pubs ready · connect PostgreSQL for the full London dataset`; renderAll(); } catch { $('#status').textContent = `The pub list is unavailable. Start the API and check ${API_URL}.`; updateCounts(); } } }
function renderMap() { if (!window.L) return; $('#map').hidden = false; if (!state.map) { state.map = L.map('map').setView([51.5074, -0.1278], 12); L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', { attribution: '© OpenStreetMap contributors' }).addTo(state.map); state.markers = L.layerGroup().addTo(state.map); } state.markers.clearLayers(); visiblePubs().slice(0, 200).forEach((pub) => { if (typeof pub.latitude !== 'number') return; const marker = L.marker([pub.latitude, pub.longitude]).bindPopup(`<strong>${pub.name.replaceAll('<','&lt;')}</strong><br>${(pub.address || '').replaceAll('<','&lt;')}`); state.markers.addLayer(marker); }); state.map.invalidateSize(); window.setTimeout(() => $('#map').scrollIntoView({ behavior: 'smooth', block: 'start' }), 60); }
function setRoute(route) { $('#explore-view').hidden = route !== 'explore'; $('#passport-view').hidden = route !== 'passport'; $('#saved-view').hidden = route !== 'saved'; document.querySelectorAll('.nav-link').forEach((button) => button.classList.toggle('active', button.dataset.route === route)); if (route === 'passport') renderPassport(); if (route === 'saved') renderSaved(); window.scrollTo({ top: 0, behavior: 'smooth' }); }

$('#search-form').addEventListener('submit', (event) => { event.preventDefault(); state.query = $('#query').value; void getRecommendations(); }); $('#query').addEventListener('input', () => { state.query = $('#query').value; state.aiResults = null; state.aiContext = null; }); $('#clear-search').addEventListener('click', () => { $('#query').value = ''; state.query = ''; state.aiResults = null; state.aiContext = null; state.filtered = state.pubs; $('#status').textContent = `${state.pubs.length} pubs ready to explore`; renderResults(); $('#query').focus(); }); document.querySelectorAll('[data-query]').forEach((button) => button.addEventListener('click', () => { $('#query').value = button.dataset.query; state.query = button.dataset.query; void getRecommendations(); })); document.querySelectorAll('[data-route]').forEach((button) => button.addEventListener('click', (event) => { event.preventDefault(); setRoute(button.dataset.route); })); document.querySelectorAll('.view-tab').forEach((button) => button.addEventListener('click', () => { state.view = button.dataset.view; document.querySelectorAll('.view-tab').forEach((item) => item.classList.toggle('active', item === button)); $('#results').hidden = state.view === 'map'; $('#map').hidden = state.view !== 'map'; if (state.view === 'map') renderMap(); })); $('#map-toggle').addEventListener('click', () => { state.view = 'map'; document.querySelector('[data-view="map"]').click(); }); $('#close-detail').addEventListener('click', () => $('#detail-dialog').close()); $('#detail-dialog').addEventListener('click', (event) => { if (event.target === $('#detail-dialog')) $('#detail-dialog').close(); }); loadPubs();
const browseControls = document.querySelector('#browse-controls');
const browseResults = document.querySelector('#results');
const browseMore = document.querySelector('#browse-more');
const browseLess = document.querySelector('#browse-less');
function setBrowseExpanded(expanded) { browseResults.classList.toggle('browse-expanded', expanded); browseMore.disabled = expanded; browseLess.disabled = !expanded; }
function hideBrowseControls() { browseControls.hidden = true; setBrowseExpanded(false); }
browseMore.addEventListener('click', () => setBrowseExpanded(true));
browseLess.addEventListener('click', () => setBrowseExpanded(false));
document.querySelector('#search-form').addEventListener('submit', hideBrowseControls);
document.querySelector('#query').addEventListener('input', hideBrowseControls);
document.querySelector('#clear-search').addEventListener('click', () => { browseControls.hidden = false; setBrowseExpanded(false); });
document.querySelectorAll('[data-query]').forEach((button) => button.addEventListener('click', hideBrowseControls));
document.addEventListener('click', (event) => { if (event.target.closest('#suggestion-chips button')) hideBrowseControls(); });
function decorateCards() { document.querySelectorAll('.pub-card[data-pub-id]').forEach((wrapper) => { if (wrapper.querySelector('.pub-rating')) return; const rating = Number(state.ratings[wrapper.dataset.pubId]); if (!rating) return; const label = document.createElement('span'); label.className = 'pub-rating'; label.textContent = `${'★'.repeat(Math.floor(rating))}${rating % 1 ? '½' : ''} ${rating.toFixed(1)}`; wrapper.querySelector('.pub-top')?.append(label); }); }
function refreshPersonalisedHeading() { const aiMode = state.aiResults !== null; const title = $('#results-title'); if (aiMode) { const nextTitle = `Your picks for “${state.query}”`; if (title.textContent !== nextTitle) title.textContent = nextTitle; const more = $('#results .view-more-button'); const nextLabel = state.recommendationsExpanded ? 'View less' : 'View more'; if (more && more.textContent !== nextLabel) more.textContent = nextLabel; } else if (!state.query && title.textContent !== 'Explore London') title.textContent = 'Explore London'; }
function ensureAiControls() { if (state.aiResults === null) return; const existing = $('#results > .view-more-button'); if (!existing || existing.parentElement.classList.contains('ai-controls')) return; const controls = document.createElement('div'); controls.className = 'ai-controls'; const more = document.createElement('button'); more.className = 'view-more-button'; more.textContent = 'View more'; more.disabled = !state.aiContext?.hasMore; more.onclick = () => { if (state.aiContext?.hasMore) void getRecommendations(state.aiOffset, true); }; const less = document.createElement('button'); less.className = 'view-more-button'; less.textContent = 'View less'; less.disabled = !state.recommendationsExpanded; less.onclick = () => { state.recommendationsExpanded = false; renderResults(); }; controls.append(more, less); existing.replaceWith(controls); }
function normaliseRecommendationStatus() { if (state.aiResults === null) return; const status = $('#status'); const next = `${state.aiResults.length} verified matches found`; if (status.textContent.includes(' of ') && status.textContent !== next) status.textContent = next; }
new MutationObserver(() => { decorateCards(); ensureAiControls(); normaliseRecommendationStatus(); }).observe(document.body, { childList: true, subtree: true });
function ensureRatingPicker() { if ($('#rating-picker')) return; const picker = document.createElement('div'); picker.id = 'rating-picker'; picker.className = 'rating-picker'; picker.setAttribute('aria-label', 'Rate this pub out of five'); for (let index = 1; index <= 10; index += 1) { const button = document.createElement('button'); button.type = 'button'; button.className = 'rating-half'; button.dataset.rating = String(index / 2); button.textContent = '★'; button.onclick = () => { picker.dataset.value = button.dataset.rating; picker.querySelectorAll('button').forEach((item) => item.classList.toggle('selected', Number(item.dataset.rating) <= Number(picker.dataset.value))); }; picker.append(button); } $('#review-text').before(picker); }
ensureRatingPicker();
